toolArgs.old_str:
// Now probe a type whose resolver deliberately excludes it.
// A resolver that only handles Person (returns null for anything else):
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new DefaultJsonTypeInfoResolver
        {
            Modifiers =
            {
                ti => { if (ti.Type == typeof(Secret)) ti = null!; }
            }
        })
};

// TryGetTypeInfo returns false when the resolver yields null for a type.
if (limited.TryGetTypeInfo(typeof(Secret), out _))
    Console.WriteLine("Probe succeeded for Secret");
else
    Console.WriteLine("Probe failed for Secret (metadata unavailable)");

record Person(string Name, int Age);
record Secret(string Value);

